/**
 * @brief Get ProAV HDR Gamma table
 * @param [in] eHdrGammaType : HDR Gamma type
 * @return ProAV HDR Gamma Table Pointer
 */
const uint08 *dvProAV_HdrGammaTableGet(HDR_GAMMA_TYPE eHdrGammaType)
{
    if (eHdrGammaType == eHdrGamma1)
        return m_ucHdrGamma1Table;
    else if (eHdrGammaType == eHdrGamma3)
        return m_ucHdrGamma3Table;
    else if (eHdrGammaType == eHdrGamma4_1)
        return m_ucHdrGamma4_1Table;
    else if (eHdrGammaType == eHdrGamma4_2)
        return m_ucHdrGamma4_2Table;
    else if (eHdrGammaType == eHdrGamma4_3)
        return m_ucHdrGamma4_3Table;
    else //if (eHdrGammaType == eHdrGamma4_4)
        return m_ucHdrGamma4_4Table;
}
